# Properly extract match function from clean_original
lines = clean_original.split('\n')
match_start_line = None
for i, line in enumerate(lines):
    if line.strip() == 'def match(version, match_expr):':
        match_start_line = i
        break

if match_start_line is not None:
    # Find end - next top-level def or class at indent 0
    func_lines = [lines[match_start_line]]
    for i in range(match_start_line + 1, len(lines)):
        line = lines[i]
        stripped = line.strip()
        if stripped and not line.startswith(' ') and (stripped.startswith('def ') or stripped.startswith('class ')):
            break
        func_lines.append(line)

    match_func_clean = '\n'.join(func_lines)

    # Verify syntax
    import ast
    try:
        ast.parse(match_func_clean)
        print("Match function AST OK!")
        print(f"Lines: {len(func_lines)}")
    except SyntaxError as e:
        print(f"SyntaxError at line {e.lineno}: {e.msg}")

    print("\nFirst 5 lines:")
    for l in func_lines[:5]:
        print(repr(l))
    print("Last 5 lines:")
    for l in func_lines[-5:]:
        print(repr(l))
else:
    print("match function not found")
